"use client";

import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "@/lib/utils";
import { Check, Minus } from "@/components/ui/icons";

// Checkbox: generated by UIX from the design system. Same variants and sizes as the Figma component.

const checkboxVariants = cva(
  "peer size-5 shrink-0 cursor-pointer appearance-none transition-colors border border-line-strong bg-surface hover:border-line-brand checked:border-transparent checked:hover:border-transparent indeterminate:border-transparent indeterminate:hover:border-transparent checked:bg-brand checked:hover:bg-brand-hover indeterminate:bg-brand indeterminate:hover:bg-brand-hover focus-visible:outline-none focus-visible:ring-3 focus-visible:ring-line-focus disabled:cursor-not-allowed disabled:border-line-default disabled:bg-disabled checked:disabled:bg-disabled indeterminate:disabled:bg-disabled rounded-sm",
);

export interface CheckboxProps
  extends Omit<React.InputHTMLAttributes<HTMLInputElement>, "type" | "size">,
    VariantProps<typeof checkboxVariants> {
  label?: React.ReactNode;
  /** Shows the dash state (mixed selection). */
  indeterminate?: boolean;
}

const Checkbox = React.forwardRef<HTMLInputElement, CheckboxProps>(
  ({ className, label, indeterminate = false, ...props }, ref) => {
    const inner = React.useRef<HTMLInputElement>(null);
    React.useImperativeHandle(ref, () => inner.current as HTMLInputElement);
    React.useEffect(() => {
      if (inner.current) inner.current.indeterminate = indeterminate;
    }, [indeterminate]);
    const box = (
      <span className="relative inline-flex size-5 shrink-0">
        <input ref={inner} type="checkbox" data-slot="checkbox" data-kind="toggle" className={cn(checkboxVariants({  }), className)} {...props} />
        <Check aria-hidden className="pointer-events-none absolute inset-0 m-auto opacity-0 size-[14px] text-fg-on-brand peer-disabled:text-fg-disabled peer-checked:opacity-100 peer-indeterminate:opacity-0" />
        <Minus aria-hidden className="pointer-events-none absolute inset-0 m-auto opacity-0 size-[14px] text-fg-on-brand peer-disabled:text-fg-disabled peer-indeterminate:opacity-100" />
      </span>
    );
    return (
      label ? (
        <label className="inline-flex cursor-pointer items-center gap-2 text-body-medium text-fg-primary has-[:disabled]:cursor-not-allowed has-[:disabled]:text-fg-disabled">
          {box}
          <span>{label}</span>
        </label>
      ) : (
        box
      )
    );
  },
);
Checkbox.displayName = "Checkbox";

export { Checkbox, checkboxVariants };
